from author import *
b=[]
def add(a,n,actions):b.append(act(a,n,actions))
def view(angle=45,orbit=False):return dict(op='view3d',angle=angle,orbit=orbit)
def key(t,k,pressed=True):return at(t,op='game_input',key=k,pressed=pressed)
def gp(t,p,v):return at(t,op='game_input',property=p,value=v)
def code(path,line):return dict(op='script',path='res://'+path,line=line)
def new(kind,**props):return dict(new=kind,props=props)
def mesh(radius):return new('SphereMesh',radius=radius,height=radius*2,radial_segments=8,rings=4,material=new('StandardMaterial3D',shading_mode=0,vertex_color_use_as_albedo=True))
def mat(node,k,v):return setp(k,v,node,resource_property='mesh',resource_chain=['material'],filter=k.replace('_',' '))
A='Read The Game And Its Contract'
add(A,'This is Signal Garden from Walker Claude. Move onto the signal pad, press E to complete the charge, then follow the open route. We are using an isolated copy of the current game, which already contains particle effects.',[dict(op='open',path='res://arena.tscn'),at(.5,op='play_custom',path='res://main.tscn'),key(1.5,'Right'),key(2.17,'Right',False),key(2.5,'E'),key(2.7,'E',False),key(5,'Right'),key(7.1,'Right',False)])
add(A,'The burst marks a milestone at its event position. The motes indicate that a route is available while the room remains active. Those are different jobs. Neither effect opens the gate or decides that the player has finished.',[dict(op='stop'),at(.5,op='play_custom',path='res://main.tscn'),key(1.5,'Right'),key(2.17,'Right',False),key(2.5,'E'),key(2.7,'E',False),key(5,'Right'),key(7.1,'Right',False)])
add(A,'Inspect the original resource settings. The burst has thirty-two particles and a seven-tenths-second lifetime. The motes have forty-eight particles and a two-second lifetime. Both are CPU particles in this game’s Compatibility renderer.',[dict(op='stop'),at(.5,op='open',path='res://baseline-effects/burst.tscn'),at(5,op='open',path='res://baseline-effects/ambient.tscn')])
add(A,'The supplied assignment snapshot calls this Assignment Seven. The working course copy has since renumbered particle work. We follow the supplied brief here: two different effects, explicit predictions, visible revisions, and separate state, appearance, and cost evidence.',[code('submission_checklist.gd',2)])
add(A,'Write the predictions before editing. A burst should survive a hidden player because the scene owns it. Hiding the scene should stop new motes. Pausing should stop particle processing without requiring the emitting property to become false.',[code('contract_predictions.gd',2)])
add(A,'This editor lab is derived from the current Signal Garden geometry. It is not a recovered historical revision. We will reintroduce the effect resources in inspectable steps, then load those resources through the existing game’s actual event paths.',[dict(op='open',path='res://arena.tscn'),at(.5,**view())])
A='Build The Milestone Burst'
add(A,'Add CPU Particles Three D at the pad. Keep it initially inactive, with thirty-two particles, a seven-tenths-second lifetime, one-shot enabled, and full explosiveness. The CPU node stores its motion controls directly, rather than using a Particle Process Material.',[setp('heading',A),at(.4,op='add',class_name='CPUParticles3D',name='Burst',properties={'position':{'v3':[-2,.4,0]},'emitting':False,'amount':32,'lifetime':.7,'one_shot':True,'explosiveness':1,'randomness':.1,'process_mode':1,'local_coords':False,'use_fixed_seed':True,'seed':7270})])
add(A,'Assign a small sphere mesh and an unshaded surface material that uses vertex colors. Now the emitter has something to draw. We keep the same low-detail mesh as the original effect while establishing its behavior.',[setp('mesh',mesh(.045),'Burst'),at(.5,**setp('color',{'color':'2ed99e'},'Burst'))])
add(A,'Launch upward between one point three and two point two meters per second, with downward gravity. Restart the preview. The burst is a short milestone cue, so its compact arc should remain close to the event it describes.',[setp('direction',{'v3':[0,1,0]},'Burst'),at(.3,**setp('initial_velocity_min',1.3,'Burst')),at(.6,**setp('initial_velocity_max',2.2,'Burst')),at(.9,**setp('gravity',{'v3':[0,-3,0]},'Burst')),at(1.2,**setp('spread',65,'Burst')),at(1.5,**setp('preview_burst',True))])
add(A,'Save the burst scene and open the event owner. The existing game adds the effect beneath its root, moves it to the event position, and restarts the single emitter. A later event intentionally replaces an active burst at the newer position.',[setp('preview_burst',False),at(.3,**setp('emitting',False,'Burst')),at(.6,op='save_branch',node='Burst',path='res://effects/burst.tscn'),at(1,op='save'),at(1.4,**code('signal-garden/garden.gd',254))])
add(A,'Run the actual game and open the gate. Then move through the route to the finish. These two inputs produce bursts at different world positions; the particle resource does not need to know which gameplay event called it.',[dict(op='play_custom',path='res://main.tscn'),key(1,'Right'),key(1.67,'Right',False),key(2,'E'),key(2.2,'E',False),key(5,'Right'),key(7.1,'Right',False)])
add(A,'Reset and repeat the gate event with the player hidden by a labeled diagnostic control. The root-owned burst remains visible at the pad. This third trial checks the ownership prediction without changing the gate’s rules.',[key(0,'R'),key(.2,'R',False),key(.5,'Right'),key(1.17,'Right',False),gp(1.5,'staged_player_hidden',True),key(2,'E'),key(2.2,'E',False),gp(7,'staged_player_hidden',False)])
A='Build The Open Route Motes'
add(A,'Return to the editor lab and add the route motes. Use forty-eight CPU particles with a two-second lifetime and a small sphere mesh. Leave emission off initially. Availability is a condition, not a burst that should fire at startup.',[dict(op='stop'),at(.4,op='open',path='res://arena.tscn'),at(.8,**view()),at(1.2,**setp('heading',A)),at(1.5,op='add',class_name='CPUParticles3D',name='Motes',properties={'position':{'v3':[3,.15,0]},'amount':48,'lifetime':2,'one_shot':False,'emitting':False,'process_mode':1,'use_fixed_seed':True,'seed':7270,'mesh':mesh(.022),'color':{'color':'b3e6b3'}})])
add(A,'Spread births through a box over the open route. Give the motes a slow upward speed and zero gravity. The volume identifies a place the player can use; it should not compete with the short milestone burst.',[setp('emission_shape',3,'Motes'),at(.3,**setp('emission_box_extents',{'v3':[1.5,.05,2]},'Motes')),at(.6,**setp('direction',{'v3':[0,1,0]},'Motes')),at(.9,**setp('initial_velocity_min',.15,'Motes')),at(1.2,**setp('initial_velocity_max',.35,'Motes')),at(1.5,**setp('gravity',{'v3':[0,0,0]},'Motes')),at(1.8,**setp('spread',10,'Motes')),at(2.1,**setp('preview_motes',True))])
add(A,'Save the initially inactive motes and inspect the game condition. New emission requires an open gate, an unfinished room, enabled presentation, and a visible scene. Existing particles may finish after that condition becomes false.',[setp('preview_motes',False),at(.3,**setp('emitting',False,'Motes')),at(.6,op='save_branch',node='Motes',path='res://effects/ambient.tscn'),at(1,op='save'),at(1.4,**code('signal-garden/garden.gd',251))])
add(A,'Open the gate again and watch the route fill. Hide the scene through the diagnostic control, then show it. The emission condition becomes false while hidden and becomes true again when the available route is visible.',[dict(op='play_custom',path='res://main.tscn'),key(1,'Right'),key(1.67,'Right',False),key(2,'E'),key(2.2,'E',False),gp(5,'visible',False),gp(8,'visible',True)])
add(A,'Pause with P and inspect the diagnostic line. The motes can still report emitting while their pausable processing stops. Resume with P and the simulation continues. Property state and visible motion are separate observations.',[key(0,'P'),key(.2,'P',False),key(5,'P'),key(5.2,'P',False)])
add(A,'Reach the finish, then reset. New motes stop at the finish, and their existing particles age out. Reset returns both effect contracts to the initial state. These off-states matter as much as the attractive active frame.',[key(0,'Right'),key(2.1,'Right',False),key(6,'R'),key(6.2,'R',False)])
A='Test Look And Tune'
add(A,'Inspect the state tests on this selected copy. The inherited suite protects movement, charging, collision, animation, and reset behavior. The particle checks add repeated input events, two positions, pause, hiding, and intentional burst replacement. A passing state check does not judge appearance.',[dict(op='stop'),at(.5,**code('tests/test-effects.gd',19))])
add(A,'Make the burst’s visual revision independently. Increase its sphere radius slightly, connect an age ramp, and enable alpha transparency. The goal is a clearer milestone at game scale with a deliberate fade, while count, lifetime, and gameplay timing remain fixed.',[dict(op='open',path='res://arena.tscn'),at(.4,**view()),at(.8,**setp('heading',A)),at(1.1,**setp('radius',.055,'Burst',resource_property='mesh')),at(1.4,**setp('height',.11,'Burst',resource_property='mesh')),at(1.7,**setp('color_ramp',{'resource':'res://effects/burst-ramp.tres'},'Burst')),at(2,**setp('scale_amount_curve',{'resource':'res://effects/burst-scale.tres'},'Burst')),at(2.3,**mat('Burst','transparency',1)),at(2.6,**setp('color',{'color':'ffffff'},'Burst')),at(2.9,**setp('preview_burst',True))])
add(A,'Save that revision and compare it through the real gate event. Judge the size, onset, and fade against the game’s floor and camera. Preserve the baseline resource and the changed settings so the comparison remains reproducible.',[setp('preview_burst',False),at(.3,**setp('emitting',False,'Burst')),at(.6,op='save_branch',node='Burst',path='res://effects/burst.tscn'),at(1,op='save'),at(1.4,op='play_custom',path='res://main.tscn'),key(2,'Right'),key(2.67,'Right',False),key(3,'E'),key(3.2,'E',False)])
add(A,'Give the motes a separate revision. A slightly larger cyan sphere, an age fade, and a grow-shrink curve distinguish route availability from the warm burst. Two seconds of pre-roll establishes the cloud when emission starts; that choice belongs to this continuous effect.',[dict(op='stop'),at(.3,op='open',path='res://arena.tscn'),at(.6,**setp('radius',.032,'Motes',resource_property='mesh')),at(.9,**setp('height',.064,'Motes',resource_property='mesh')),at(1.2,**setp('color_ramp',{'resource':'res://effects/ambient-ramp.tres'},'Motes')),at(1.5,**setp('scale_amount_curve',{'resource':'res://effects/ambient-scale.tres'},'Motes')),at(1.8,**mat('Motes','transparency',1)),at(2.1,**setp('preprocess',2,'Motes')),at(2.4,**setp('color',{'color':'ffffff'},'Motes')),at(2.7,**setp('preview_motes',True))])
add(A,'Save the motes and inspect both revised effects in the same gameplay view. Their visual jobs should remain different. Keep the baseline and historical course-series resources separate from this new revision; none of those files is a substitute for this comparison.',[setp('preview_motes',False),at(.3,**setp('emitting',False,'Motes')),at(.6,op='save_branch',node='Motes',path='res://effects/ambient.tscn'),at(1,op='save'),at(1.4,op='play_custom',path='res://main.tscn'),key(2,'Right'),key(2.67,'Right',False),key(3,'E'),key(3.2,'E',False),key(7,'Right'),key(9.1,'Right',False)])
add(A,'Run the selected-version checks after the changes. Keep machine findings, visual findings, and remaining questions in different report sections. The useful conclusion is what was observed, including an unsuccessful revision, rather than a blanket claim that the effect is good.',[dict(op='stop'),at(.4,**code('test_evidence.gd',2))])
A='Measure The Cost'
add(A,'Open the CPU measurement fixture. It compares an empty baseline with the burst workload, the motes, and both. Each condition uses sixty warm-up frames and three hundred timed frames, repeated three times in each of three fresh processes.',[code('tests/price-cpu.gd',3)])
add(A,'The burst fixture loops the short event as an upper-bound workload. The actual game intentionally has one burst emitter, so replacement does not create unbounded overlapping instances. Keep that design choice beside the measurement rather than benchmarking an invented game.',[code('tests/price-cpu.gd',7)])
add(A,'Read the measured CPU table. These values are wall time per simulated frame under fixed sixty-hertz execution. They do not establish interactive frame rate or GPU cost. Subtracting the empty fixture is useful, but small differences still include measurement noise.',[dict(op='play_custom',path='res://price_report.tscn')])
add(A,'Now inspect the separate renderer instrument. It uses the actual game viewport and records effect-off and effect-on conditions at twelve-eighty by seven-twenty. It reports draw calls and available viewport timings, with the machine and renderer named.',[dict(op='stop'),at(.4,**code('tests/price-render.gd',3))])
add(A,'Read the renderer results with their availability flags. A missing GPU timer stays unavailable; zero is not evidence of free drawing. The CPU fixture and the rendered scene answer related questions with different instruments.',[dict(op='play_custom',path='res://price_report.tscn'),gp(1,'show_renderer',True)])
add(A,'A sixty-frame target gives roughly sixteen point seven milliseconds for the whole frame. This brief reserves two milliseconds for combined effect work, including drawing. The budget needs complete renderer evidence and room for the rest of the game, not just a fast headless result.',[dict(op='stop'),at(.4,**code('contract_predictions.gd',17))])
A='Package The Assignment'
add(A,'Inspect the source package. It includes the Godot project, change brief, tests, reports, asset sources, and the actual capture records. The supplied Assignment Seven brief governs this example even though the current course folders use different numbering.',[code('submission_checklist.gd',2)])
add(A,'Record a submission-style walkthrough through the ordinary controls: a gate event, a reset and repeated event, and a finish at a second position. Keep the diagnostic-input label when the recording is scripted. Do not call it a human playtest.',[dict(op='play_custom',path='res://main.tscn'),key(1,'Right'),key(1.67,'Right',False),key(2,'E'),key(2.2,'E',False),key(5,'R'),key(5.2,'R',False),key(5.5,'Right'),key(6.17,'Right',False),key(6.5,'E'),key(6.7,'E',False),key(9,'Right'),key(11.1,'Right',False)])
add(A,'Show the condition and pause behavior in that same walkthrough. Pause, resume, and reset are observable parts of the effect contract. Preserve a complete smoke or mote tail instead of cutting immediately after the event’s bright onset.',[key(0,'R'),key(.2,'R',False),key(.5,'Right'),key(1.17,'Right',False),key(1.5,'E'),key(1.7,'E',False),key(4,'P'),key(4.2,'P',False),key(7,'P'),key(7.2,'P',False),key(10,'R'),key(10.2,'R',False)])
add(A,'For the student submission, record the exact source revision and apply the a-seven tag. Verify a clean clone. Record the media filename and its hash beside that source. Keep large video and audio files outside the code repository, with reviewer access checked.',[dict(op='stop'),at(.5,**code('submission_checklist.gd',12))])
add(A,'The linked rubric divides the work into sixty, ten, ten, and twenty points. Use the assignment’s own criteria when checking the package. A production script cannot promise comparative quartile points, and this local review does not upload or submit anything.',[code('submission_checklist.gd',22)])
add(A,'Return to Signal Garden. The finished engineering story connects an event and a condition to visible effects, preserves one revision for each, and states the limits of the tests and measurements. That is the work the particle count alone cannot explain.',[dict(op='play_custom',path='res://main.tscn'),key(1,'Right'),key(1.67,'Right',False),key(2,'E'),key(2.2,'E',False)])
d=dict(slug='claude-liam-lecture-adding-particle-effects-to-walker-claude',title='Adding Particle Effects to Walker Claude',payoff='Connect two effects to real game contracts',summary='Build, revise, test, and price a milestone burst and open-route motes in Signal Garden.',framing='Can a good-looking preset prove that an effect belongs in a game? We will connect two different visual jobs to the real game, then check their behavior, revisions, and cost.',question='A good effect is\na good-looking preset',trigger='good-looking preset',replacement='tested game contract',terms=[dict(term='Event',meaning='A specific occurrence that can trigger a burst'),dict(term='Condition',meaning='A state that can allow ongoing emission'),dict(term='Revision',meaning='A preserved change with a reason and comparison'),dict(term='Baseline',meaning='The comparison condition used by a test')],body=b,recap=['A milestone burst belongs to a real event and position.','Route motes follow an explicit availability condition.','Pause, hiding, reset, and replacement are part of the contract.','State checks and visual revisions establish different evidence.','CPU and renderer measurements need separate context.','A traceable source and media package makes the work reviewable.'],prompt='Add one gameplay burst and one continuous effect with a different job to your Walker game. Write their intent, predict three failures, implement in small steps, and record one visual revision and both kinds of cost evidence.',checks=['Check: the event and condition are correct in real play.','Check: reports distinguish state, appearance, and cost.'],coverage='Six acts: exact Signal Garden source and supplied Assignment 7; original baseline and explicitly derived teaching starter; CPU burst/motes construction through native editor properties and saved scenes; actual event ownership and condition source; ordinary input gate/reset/finish trials at two positions; pause/hide/reset/replacement checks; separately motivated appearance revisions; 60/300/3/3 headless CPU protocol and independent renderer instrument; traceable source/media and instructional submission route. Native visual comparison, renderer pricing and completed narration/capture QC remain required.',facts='Baseline inherited 32-check suite passed. Selected provisional tuned source passed 32 regression checks and 17 additional particle-contract checks. Headless CPU measurement produced 36 rows, with 60 warm-up and 300 timed frames, 3 repetitions in each of 3 fresh processes. No GPU or human visual approval follows. The real game uses a root-owned single CPUParticles3D burst with intentional replacement and pausable motes whose emitting flag may remain true during pause. The copied source and later historical course-series tuning are preserved separately. Native capture is blocked while the Mac is locked; visual revisions remain hypotheses until observed.',sources='Copied current /Users/bear/Documents/CoWork/bear-textbooks/books/walker-claude/godot/signal-garden, with exact source HEAD and file hashes in SOURCE-PROVENANCE.json. Historical tuning resources copied separately from godot/course-series/effects. Supplied assignment /Users/bear/Downloads/seis-course-publish/assignments/07-particle-effects.md. Official Godot CPUParticles3D, Input and RenderingServer documentation.')
